import * as THREE from 'three/webgpu';
import { uv, float, vec3, vec4, mix, smoothstep, uniform, positionLocal } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'bento-metrics-grid';
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const colors = (config.visualSpec && config.visualSpec.colors) || {
    surface: '#14141a', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#101017' }, { at: 1, hex: '#1a1a22' }]
  };

  const disposables = [];
  const timelines = [];

  function makeGradientMaterial() {
    const cA = new THREE.Color(colors.gradientStops[0].hex);
    const cB = new THREE.Color(colors.gradientStops[1].hex);
    const uvNode = uv();
    const diag = uvNode.x.add(uvNode.y).mul(0.5);
    let grad = mix(vec3(cA.r, cA.g, cA.b), vec3(cB.r, cB.g, cB.b), diag);

    // hard-stop sheen band at 40% width 0.15
    const bandCenter = float(0.4);
    const bandHalf = float(0.075);
    const bandMask = smoothstep(bandCenter.sub(bandHalf), bandCenter.sub(bandHalf).add(0.02), diag)
      .mul(float(1.0).sub(smoothstep(bandCenter.add(bandHalf).sub(0.02), bandCenter.add(bandHalf), diag)));
    grad = grad.add(vec3(0.06, 0.06, 0.06).mul(bandMask));

    const mat = new THREE.MeshStandardNodeMaterial({
      roughness: 0.5,
      metalness: 0.45,
    });
    mat.colorNode = vec4(grad, 1.0);
    if ('clearcoat' in mat) {
      mat.clearcoat = 0.2;
      mat.clearcoatRoughness = 0.3;
    }
    disposables.push(mat);
    return mat;
  }

  function makeChamferGeo(w, h, d) {
    const geo = new THREE.BoxGeometry(w, h, d, 1, 1, 1);
    disposables.push(geo);
    return geo;
  }

  function makeCell({ x, y, w, h, depth, valueText, valueSize, labelText }) {
    const cellGroup = new THREE.Group();
    cellGroup.position.set(x, y, 0);

    const mat = makeGradientMaterial();
    const geo = makeChamferGeo(w, h, depth);
    const slab = new THREE.Mesh(geo, mat);
    cellGroup.add(slab);

    // tick bar top-left inside padding
    const tickGeo = new THREE.BoxGeometry(0.4, 0.05, depth + 0.01);
    disposables.push(tickGeo);
    const tickMat = new THREE.MeshStandardNodeMaterial({
      color: new THREE.Color(colors.accent),
      emissive: new THREE.Color(colors.accent),
      emissiveIntensity: 1.3,
      roughness: 0.4,
      metalness: 0.2,
    });
    disposables.push(tickMat);
    const tick = new THREE.Mesh(tickGeo, tickMat);
    tick.position.set(-w / 2 + 0.5 + 0.2, h / 2 - 0.5 - 0.025, depth / 2 + 0.005);
    cellGroup.add(tick);

    // value text
    const valueMesh = createTextMesh({
      text: valueText,
      fontAtlas: ctx.fontAtlas,
      family: 'Lora',
      fontWeight: 600,
      fontSize: valueSize,
      color: colors.paper || '#e8ecf2',
    });
    valueMesh.position.set(-w / 2 + 0.5, 0.05, depth / 2 + 0.01);
    cellGroup.add(valueMesh);
    disposables.push(valueMesh);

    // label text
    const labelMesh = createTextMesh({
      text: labelText,
      fontAtlas: ctx.fontAtlas,
      family: 'JetBrains Mono',
      fontWeight: 400,
      fontSize: 18,
      color: colors.paper || '#e8ecf2',
    });
    labelMesh.position.set(-w / 2 + 0.5, -valueSize * 0.62 - 0.05, depth / 2 + 0.01);
    cellGroup.add(labelMesh);
    disposables.push(labelMesh);

    cellGroup.userData.baseScale = 1;
    return cellGroup;
  }

  const depth = 0.06;
  const dominant = makeCell({
    x: -1.125, y: 0, w: 3.25, h: 3.5, depth,
    valueText: '0.002 mm', valueSize: 0.62,
    labelText: 'Case tolerance, CNC pass',
  });
  group.add(dominant);

  const secTop = makeCell({
    x: 1.75, y: 0.9375, w: 2.0, h: 1.625, depth,
    valueText: '38 h', valueSize: 0.34,
    labelText: 'Power reserve, NA-01',
  });
  group.add(secTop);

  const secBottom = makeCell({
    x: 1.75, y: -0.9375, w: 2.0, h: 1.625, depth,
    valueText: '214', valueSize: 0.34,
    labelText: 'Components per calibre',
  });
  group.add(secBottom);

  // header caption
  const captionMesh = createTextMesh({
    text: 'ATELIER METRICS / Q2 2026',
    fontAtlas: ctx.fontAtlas,
    family: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 18,
    color: colors.paper || '#e8ecf2',
  });
  captionMesh.position.set(-2.75, 2.0, 0);
  group.add(captionMesh);
  disposables.push(captionMesh);

  const cells = [dominant, secTop, secBottom];

  // entrance animation: stagger-cards + fade-up, dominant first
  cells.forEach((cell, i) => {
    cell.traverse((child) => {
      if (child.material && 'opacity' in child.material) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });
    const originalY = cell.position.y;
    cell.position.y = originalY + 0.2;
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(cell.position, {
      y: originalY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    cell.traverse((child) => {
      if (child.material && 'opacity' in child.material) {
        tl.to(child.material, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
      }
    });
    timelines.push(tl);
  });

  // hover handlers (press-down / weighted-settle)
  function hoverIn(cell) {
    return () => {
      const tl = gsap.timeline();
      tl.to(cell.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' });
      timelines.push(tl);
    };
  }
  function hoverOut(cell) {
    return () => {
      const tl = gsap.timeline();
      tl.to(cell.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.001 })
        .to(cell.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' });
      timelines.push(tl);
    };
  }

  group.userData.handlers = {
    onCellHoverIn: (idx) => hoverIn(cells[idx])(),
    onCellHoverOut: (idx) => hoverOut(cells[idx])(),
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
  };

  return group;
}
